[CmdletBinding()]
param([Parameter(Mandatory)][string]$ServerName,[Parameter(Mandatory)][string]$ClaimId,[Parameter(Mandatory)][bool]$Succeeded,[string]$ConfigPath=(Join-Path (Split-Path -Parent $PSScriptRoot) 'config\agents.json'),[string]$CodexHome)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop';if(-not(Get-Command Get-EcosystemStateRoot -ErrorAction SilentlyContinue)){Import-Module (Join-Path $PSScriptRoot 'AgentEcosystem.psm1') -Global}
$config=Get-EcosystemConfig -ConfigPath $ConfigPath -CodexHome $CodexHome;$root=Join-Path (Get-EcosystemStateRoot -Config $config -CodexHome $CodexHome) 'health\mcp';$path=Join-Path $root ($ServerName+'.json');$lock=$path+'.lock';$stream=[IO.File]::Open($lock,[IO.FileMode]::OpenOrCreate,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None);try{$state=Get-Content $path -Raw|ConvertFrom-Json;if([string]$state.canaryClaimId -ne $ClaimId){throw 'Canary claim is not owned by this run.'};if($Succeeded){$state.probeSuccessCount=[int]$state.probeSuccessCount+1;if($state.probeSuccessCount -ge [int]$config.mcp.resilience.requiredSuccessfulProbes){$state.state='healthy';$state.canaryClaimId=$null}else{$state.canaryClaimId=$null}}else{$state.state='open';$state.probeSuccessCount=0;$state.canaryClaimId=$null;$state.retryAfterUtc=[DateTime]::UtcNow.AddSeconds([int]$config.mcp.resilience.circuitOpenSeconds).ToString('o')};$tmp=$path+'.'+[guid]::NewGuid().ToString('N')+'.tmp';[IO.File]::WriteAllText($tmp,(($state|ConvertTo-Json -Depth 8)+[Environment]::NewLine));Move-Item $tmp $path -Force;[pscustomobject]$state}finally{$stream.Dispose()}
